edits.after:
static void nsim_queue_uninit(struct netdevsim *ns)
{
	struct net_device *dev = ns->netdev;
	int i;

	for (i = 0; i < dev->num_rx_queues; i++)
		__netif_napi_del(&ns->rq[i]->napi);

	synchronize_net();

	for (i = 0; i < dev->num_rx_queues; i++)
		nsim_queue_free(ns->rq[i]);

	kfree(ns->rq);
	ns->rq = NULL;
}

